with candidate (n, title, artist, image_url, content, image_license, image_credit, image_page) as (
    values
    (1, '牛乳を注ぐ女', 'ヨハネス・フェルメール', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/20/Johannes_Vermeer_-_Het_melkmeisje_-_Google_Art_Project.jpg/960px-Johannes_Vermeer_-_Het_melkmeisje_-_Google_Art_Project.jpg', '1657〜58年頃に描かれ、アムステルダム国立美術館が所蔵する作品です。左の窓から射し込む光のなかで、女性が静かに牛乳を注いでいます。パンや籠には光の粒を置く点描の技法が使われ、エプロンの青には高価なラピスラズリから作るウルトラマリンが使われました。白い壁にも釘や釘穴、染みまで描き込まれています。X線調査では、壁の地図や床の籠が完成作では消されたことがわかっており、画面を簡潔に整えた工夫がうかがえます。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Johannes_Vermeer_-_Het_melkmeisje_-_Google_Art_Project.jpg'),
    (2, '朝顔図屏風', '鈴木其一', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/16/%E6%9C%9D%E9%A1%94%E5%9B%B3%E5%B1%8F%E9%A2%A8-Morning_Glories_MET_DT1587.jpg/960px-%E6%9C%9D%E9%A1%94%E5%9B%B3%E5%B1%8F%E9%A2%A8-Morning_Glories_MET_DT1587.jpg', '酒井抱一の弟子で、江戸琳派を受け継いだ鈴木其一による六曲一双の屏風です。メトロポリタン美術館が所蔵し、各隻は縦178.2センチ、横379.8センチの大画面です。金地の上に、青い朝顔の花と緑の葉がつるを伸ばしながら連なり、花と葉の繰り返しが画面にリズムを生んでいます。其一の支援者だった松澤家に伝わったものとされます。都会的に洗練された装飾性は、近代の日本画を先取りしたものと評価されています。', 'CC0', null, 'https://commons.wikimedia.org/wiki/File:朝顔図屏風-Morning_Glories_MET_DT1587.jpg')
), fresh as (
    select c.*, row_number() over (order by c.n) as k
    from candidate c
    where not exists (select 1 from public.daily_columns d where d.title = c.title)
), free_day as (
    select day::date as display_date, row_number() over (order by day) as k
    from generate_series(
        (now() at time zone 'Asia/Tokyo')::date,
        (now() at time zone 'Asia/Tokyo')::date + 2
            + (select count(*)::int from public.daily_columns
               where display_date >= (now() at time zone 'Asia/Tokyo')::date),
        interval '1 day') as day
    where not exists (select 1 from public.daily_columns d where d.display_date = day::date)
)
insert into public.daily_columns (title, artist, image_url, content, image_license, image_credit, image_page, display_date)
select f.title, f.artist, f.image_url, f.content, f.image_license, f.image_credit, f.image_page, d.display_date
from fresh f join free_day d using (k)
on conflict (display_date) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('サントリー美術館、2027年に国宝・鳥獣戯画展', '六本木開館20周年を記念し、切子、司馬江漢、国宝《鳥獣戯画》、館蔵の国宝・重要文化財を紹介する4展を予定。', 'サントリー美術館（東京都港区）が2027年の展覧会スケジュールを発表した。2027年3月30日に六本木移転開館20周年を迎えるのを記念し、4つの展覧会を予定している。第1弾は同館で18年ぶりの切子展「切子 KIRIKO」（3月10日～5月16日）、第2弾は日本初の腐食銅版画を成功させた絵師を紹介する「司馬江漢の世界（仮称）」（6月23日～8月15日）。第3弾「鳥獣戯画（仮称）」（9月15日～10月24日）では、2007年の六本木開館記念展以来20年ぶりに国宝《鳥獣戯画》を展観する。第4弾「都市の居間（仮称）」（11月27日～2028年1月10日）では館蔵の国宝・重要文化財全20件を展示する。', '', '展覧会', 'https://artexhibition.jp/topics/news/20261030-AEJ3031533/',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('静嘉堂、山本芳翠《天女》など2027年度5展', '静嘉堂文庫美術館が2027年度の展覧会スケジュールを発表。初公開の源氏絵や山本芳翠の大作の一挙公開など5展を予定。', '静嘉堂文庫美術館（東京都千代田区）が2027年度の展覧会スケジュールを発表した。2027年1月から2028年3月にかけて5つの展覧会を予定している。「おひなさまと浮世絵の源氏絵」（1月30日～3月28日）では歌川国貞らによる源氏絵をすべて初公開し、「日本のやきもの」（4月10日～6月27日）は丸の内で初、16年ぶりの日本陶磁展となる。夏は刀剣展「みやこのかたな」（7月10日～9月26日）。丸の内開館5周年記念展「美の福音」（10月9日～2028年1月10日）では、山本芳翠がパリ留学中に描いた《天女》と《十二支》を一挙公開する。', '', '展覧会', 'https://artexhibition.jp/topics/news/20261030-AEJ3031620/',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('聖アンデレの磔刑', 'The Crucifixion of Saint Andrew', 'カラヴァッジョ', 'Caravaggio',
        1607,
        (select slug from public.art_movements where slug = 'baroque'),
        'クリーブランド美術館', 'https://openaccess-cdn.clevelandart.org/1976.2/1976.2_web.jpg', '1世紀にギリシャで布教し、十字架にかけられた聖アンデレの最期を描いた祭壇画です。伝承では、アンデレは十字架の上から2日間説教を続け、群衆の求めで刑吏が縄を解こうとしたものの手が動かなくなり、望みどおり殉教しました。カラヴァッジョは処刑を公開の見せ物ではなく身近な出来事として描き、強い明暗の対比で神の存在を感じさせます。ふつうX字形で描かれる十字架を、ここでは縦の十字架にしています。ルネサンスの理想化から離れ、劇的な光で生身の人間を浮かび上がらせる描き方は、バロック絵画の出発点となりました。',
        'CC0', 'The Cleveland Museum of Art', 'https://clevelandart.org/art/1976.2')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('キューピッドとプシュケ', 'Cupid and Psyche', 'ジャック＝ルイ・ダヴィッド', 'Jacques-Louis David',
        1817,
        (select slug from public.art_movements where slug = 'neoclassicism'),
        'クリーブランド美術館', 'https://openaccess-cdn.clevelandart.org/1962.37/1962.37_web.jpg', '人間の娘プシュケのもとに、正体を知られないことを条件に毎夜通う愛の神キューピッドを描いた作品です。ふつう理想的な少年として描かれるキューピッドを、ダヴィッドはぎこちない十代の若者として、にやりと笑う姿で表しました。当時刊行されたモスコスのギリシャ詩が、キューピッドを意地の悪い子どもとして描いたことなどに着想を得ています。眠るプシュケの上と寝台の台座には、2匹の蝶が描かれています。古代に学んだ明快な輪郭と構図という新古典主義の型を守りながら、理想の愛と生身の現実のずれを持ち込んだ晩年の作品です。',
        'CC0', 'The Cleveland Museum of Art', 'https://clevelandart.org/art/1962.37')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('読書', 'Reading', 'ベルト・モリゾ', 'Berthe Morisot',
        1873,
        (select slug from public.art_movements where slug = 'impressionism'),
        'クリーブランド美術館', 'https://openaccess-cdn.clevelandart.org/1950.89/1950.89_web.jpg', '画家の姉エドマが、野原に広げたショールの上に座り、本に目を落とす姿を描いた作品です。日傘と扇は草の上に置かれ、白いドレスは屋外の光と影を映し、小さな花模様が野の花と響き合います。X線調査では、エドマの目がもとはこちらを見つめていたのを、モリゾが描き直したことがわかっています。見る人を見返すマネの人物とは違い、モリゾの人物は手仕事や物思いに没頭していることが多いのです。マネに学びつつ、ゆるやかな筆づかいで戸外の光をとらえる印象派の描き方を、身近な女性の時間に向けた画家の姿勢がよく表れています。',
        'CC0', 'The Cleveland Museum of Art', 'https://clevelandart.org/art/1950.89')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('サーカスのレスラー', 'Wrestlers in a Circus', 'エルンスト・ルートヴィヒ・キルヒナー', 'Ernst Ludwig Kirchner',
        1909,
        (select slug from public.art_movements where slug = 'expressionism'),
        'クリーブランド美術館', 'https://openaccess-cdn.clevelandart.org/1966.49/1966.49_web.jpg', '色鮮やかなマットの上で、たくましいレスラーたちが危うく組み合う場面を描いた作品です。都会の暮らしの場面で知られるキルヒナーは、ゆるい筆づかいで、激しく動く体のぶれをとらえました。叫ぶ観客に囲まれて試合を見ているような迫力があります。ポスト印象派やフォーヴィスムの強い色づかいに学びながら、見たままの色よりも感情の高ぶりを色と形で表そうとしたドイツ表現主義の特徴がよく表れています。1930年代には、彼の作品639点がドイツの美術館から撤去されました。',
        'CC0', 'The Cleveland Museum of Art', 'https://clevelandart.org/art/1966.49')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;
